import React, { useEffect, useState } from 'react';
import { useSearchParams } from 'react-router-dom';
import styled from 'styled-components';

const PreviewContainer = styled.div`
  width: 100%;
  height: 100vh;
  display: flex;
  flex-direction: column;
  background: #f5f5f5;
`;

const Header = styled.div`
  background: white;
  padding: 16px 24px;
  border-bottom: 1px solid #e0e0e0;
  display: flex;
  justify-content: space-between;
  align-items: center;
`;

const Title = styled.h1`
  margin: 0;
  font-size: 18px;
  color: #333;
`;

const DownloadButton = styled.button`
  background: #007bff;
  color: white;
  border: none;
  padding: 8px 16px;
  border-radius: 4px;
  cursor: pointer;
  font-size: 14px;

  &:hover {
    background: #0056b3;
  }
`;

const PDFViewer = styled.iframe`
  flex: 1;
  width: 100%;
  border: none;
  background: white;
`;

const LoadingMessage = styled.div`
  display: flex;
  justify-content: center;
  align-items: center;
  height: 100%;
  font-size: 16px;
  color: #666;
`;

const ErrorMessage = styled.div`
  display: flex;
  justify-content: center;
  align-items: center;
  height: 100%;
  font-size: 16px;
  color: #d32f2f;
`;

const PDFPreview: React.FC = () => {
  const [searchParams] = useSearchParams();
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const companyCode = searchParams.get('company');
  const uuid = searchParams.get('uuid');

  useEffect(() => {
    if (!companyCode || !uuid) {
      setError('필수 파라미터가 누락되었습니다.');
      setLoading(false);
      return;
    }

    // PDF URL 생성
    const pdfUrl = `${window.location.origin}/api/file/estimate/download/${companyCode}/${uuid}.pdf`;

    // iframe이 로드되면 로딩 상태 해제
    const iframe = document.getElementById('pdf-iframe') as HTMLIFrameElement;
    if (iframe) {
      iframe.onload = () => {
        setLoading(false);
      };
      iframe.onerror = () => {
        setError('PDF를 불러올 수 없습니다.');
        setLoading(false);
      };
    }
  }, [companyCode, uuid]);

  const handleDownload = () => {
    if (companyCode && uuid) {
      const downloadUrl = `${window.location.origin}/api/file/estimate/download/${companyCode}/${uuid}.pdf`;
      const link = document.createElement('a');
      link.href = downloadUrl;
      link.download = `견적서_${uuid}.pdf`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    }
  };

  if (error) {
    return (
      <PreviewContainer>
        <Header>
          <Title>견적서 미리보기</Title>
        </Header>
        <ErrorMessage>{error}</ErrorMessage>
      </PreviewContainer>
    );
  }

  return (
    <PreviewContainer>
      <Header>
        <Title>견적서 미리보기</Title>
        <DownloadButton onClick={handleDownload}>
          다운로드
        </DownloadButton>
      </Header>

      {loading && <LoadingMessage>PDF를 불러오는 중...</LoadingMessage>}

      {companyCode && uuid && (
        <PDFViewer
          id="pdf-iframe"
          src={`${window.location.origin}/api/file/estimate/download/${companyCode}/${uuid}.pdf`}
          title="견적서 PDF"
        />
      )}
    </PreviewContainer>
  );
};

export default PDFPreview;
